'use strict';
// Design-only renderer. Data is supplied by the controller's local allow-listed server.
const source=window.PREVIEW_DATA||{};
const appearances={original:'Original',prism:'Prism',navy:'Navy & Cream',aurora:'Aurora'};
const roleNames={member:'Member',leader:'Department leader',admin:'Administrator',presider:'Presider'};
const departments={'Worship':['Presider','Sermon','Prayer of Thanks','Closing Prayer'],'Usher Sisters':['Usher Door','Usher Front','Usher Back'],'Usher Brothers':['Usher #1','Usher #2','Lobby Security'],'Lobby':['Lobby Desk #1','Lobby Desk #2'],'Translation':['Translation #1','Translation #2'],'Media':['Media Booth #1','Media Booth #2'],'Parking Lot':['Parking #1','Parking #2','Parking #3','Parking #4','Parking #5'],'Offering':['Offering #1','Offering #2','Offering #3','Offering #4','Offering #5','Offering #6']};
const serviceLabels=['Morning','Afternoon','Evening','Early Morning','Commemoration'];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=value=>JSON.parse(JSON.stringify(value));
const query=new URLSearchParams(location.search);
const clockParts=new Intl.DateTimeFormat('en-US',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'America/Los_Angeles'}).formatToParts(new Date());
const clock=Object.fromEntries(clockParts.filter(part=>part.type!=='literal').map(part=>[part.type,part.value]));
const today=`${clock.year}-${clock.month}-${clock.day}`;
const nowMinutes=Number(clock.hour)*60+Number(clock.minute);
function minuteOf(time){const m=String(time||'').match(/^(\d{1,2}):(\d{2})(?:\s*(AM|PM))?/i);if(!m)return 0;let hour=Number(m[1]);if(m[3])hour=hour%12+(m[3].toUpperCase()==='PM'?12:0);return hour*60+Number(m[2]);}
const services=(Array.isArray(source.services)?source.services:[]).filter(r=>/^\d{4}-\d{2}-\d{2}$/.test(r.date)).map((r,i)=>({...r,id:String(r.id||`preview-${i}`),month:r.date.slice(0,7),dateObj:new Date(`${r.date}T12:00:00Z`),minutes:minuteOf(r.time),assignmentsLoaded:Object.hasOwn(r,'assignments')&&r.assignments!==null&&typeof r.assignments==='object'})).sort((a,b)=>a.date.localeCompare(b.date)||a.minutes-b.minutes);
const members=(Array.isArray(source.members)?source.members:[]).map((m,i)=>typeof m==='string'?{id:String(i),name:m}:{id:String(m.id||i),name:String(m.displayName||m.name||'')}).filter(m=>m.name);
const songs=(Array.isArray(source.songs)?source.songs:[]).map(song=>({...song,id:String(song.id),number:String(song.number??''),title:String(song.title||''),category:String(song.category||'')})).filter(song=>song.title);
const months=[...new Set(services.map(s=>s.month))];
const currentMonth=`${clock.year}-${clock.month}`;
const defaults={member:'#duties',leader:'#manage/schedule',admin:'#manage/attention',presider:'#songs/my-service'};
const initialRole=Object.hasOwn(roleNames,query.get('role'))?query.get('role'):'leader';
const state={role:initialRole,appearance:document.documentElement.dataset.appearance||'navy',route:location.hash||defaults[initialRole],month:months.includes(currentMonth)?currentMonth:months.at(-1),search:'',openOnly:false,department:'Worship',selectedService:null,selectedMember:'',memberSearch:'',memberPage:1,attention:'requests',songSearch:'',songPage:1,songFilter:'all',songCategory:'all',selectedSong:null,historySearch:'',historyFilter:'all',simulation:'normal',songSimulation:'normal',scene:'normal',scroll:{},origin:{},returnAppearance:null,demoEditing:false};
const storageKey='weekbook-design-drafts-v4';
let stored={};try{const value=JSON.parse(localStorage.getItem(storageKey)||'{}');if(value&&typeof value==='object'&&!Array.isArray(value))stored=value;}catch(_){}
const drafts=new Map();
let pendingLeave=null;
let busy=false;
let flash='';
const app=document.querySelector('#app');
const previewDialog=document.querySelector('#preview-dialog');
const leaveDialog=document.querySelector('#leave-dialog');
const infoDialog=document.querySelector('#info-dialog');
const dateText=(s,options={month:'short',day:'numeric'})=>s.dateObj.toLocaleDateString('en-US',{...options,timeZone:'UTC'});
function timeText(s){if(!s.time)return 'Time not loaded';const minutes=s.minutes;return `${Math.floor(minutes/60)%12||12}:${String(minutes%60).padStart(2,'0')} ${minutes>=720?'PM':'AM'}`;}
function monthText(month){return month?new Date(`${month}-01T12:00:00Z`).toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'}):'No month loaded';}
function getService(id){return services.find(s=>s.id===id);}
function nextService(){return services.find(s=>s.date>today||s.date===today&&s.minutes>=nowMinutes)||services.at(-1);}
function selectedService(){return getService(state.selectedService)||nextService();}
function servicePath(prefix,service){return `#${prefix}/${encodeURIComponent(service.id)}`;}
function routeId(){try{return decodeURIComponent(state.route.split('/').slice(1).join('/'));}catch(_){return '';}}
function canManage(){return state.role==='leader'||state.role==='admin';}
function canSongs(){return state.role==='presider'||state.role==='admin';}
function currentDuties(){return departments[state.department]||departments.Worship;}
function assignmentValue(record,duty){if(!record.assignmentsLoaded)return {kind:'unknown',text:'Assignments not loaded'};if(!Object.hasOwn(record.assignments,duty))return {kind:'unknown',text:'Not provided in snapshot'};const value=record.assignments[duty];if(value===null||value==='')return {kind:'open',text:'Unassigned'};return {kind:'assigned',text:String(value)};}
function namesFor(record){return currentDuties().map(d=>assignmentValue(record,d)).filter(v=>v.kind==='assigned').map(v=>v.text);}
function openDuties(record){return currentDuties().filter(d=>assignmentValue(record,d).kind==='open');}
function liveAssignments(record){const d=drafts.get(`service:${record.id}:${state.department}`);return d?.status==='saved'?d:null;}
function drawAssignment(record,duty){const local=liveAssignments(record);if(local&&Object.hasOwn(local.values,duty))return local.values[duty]?{kind:'assigned',text:local.values[duty]}:{kind:'open',text:'Unassigned (local demo)'};return assignmentValue(record,duty);}
function draftFor(key,initial={}){if(!drafts.has(key)){const saved=stored[key];drafts.set(key,{key,values:clone(saved||initial),baseline:clone(saved||initial),dirty:false,status:saved?'saved':'unchanged'});}return drafts.get(key);}
function draftKey(){const r=state.route;if(r.startsWith('#edit/'))return `service:${routeId()}:${state.department}`;if(r==='#availability')return 'availability';if(r==='#reminders')return 'reminders';if(r.startsWith('#manage/profile/'))return `profile:${r.slice(16)}`;if(r==='#manage/settings')return 'settings';if(r==='#manage/invite')return 'invite';if(r==='#manage/add-member')return 'add-member';if(r.startsWith('#songs/'))return `songs:${selectedService()?.id||'none'}`;return null;}
function activeDraft(){const key=draftKey();return key?drafts.get(key):null;}
const svgPaths={duties:'<path d="M8 3h8l4 4v14H4V3h4m0 8 2 2 5-5m-7 9h8"/>',schedule:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h2m4 0h2m-8 4h2"/>',songs:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',manage:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0112 0v2m1-15a3 3 0 010 6m2 3a5 5 0 013 5"/>'};
function icon(key){return `<svg viewBox="0 0 24 24" aria-hidden="true">${svgPaths[key]}</svg>`;}
function link(label,path,classes=''){return `<a class="${classes}" href="${esc(path)}" data-route="${esc(path)}">${label}</a>`;}
function button(label,action,extra=''){return `<button data-action="${action}" ${extra}>${label}</button>`;}
function unavailable(title,description,action=''){return `<section class="panel quiet-panel"><h2>${title}</h2><p>${description}</p>${action}</section>`;}
function sourceLine(){const captured=source.capturedAt?new Date(source.capturedAt):null;const valid=captured&&!Number.isNaN(captured.getTime());return `<div class="source-line"><span>Schedule snapshot${valid?' · '+captured.toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'America/Los_Angeles'}):''}</span><span>Pacific time</span></div>`;}
function nav(){const items=[['My duties','#duties','duties'],['Schedule','#schedule','schedule']];if(canSongs())items.push(['Songs','#songs/my-service','songs']);if(canManage())items.push(['Manage',state.role==='admin'?'#manage/attention':'#manage/schedule','manage']);let active=state.route.startsWith('#manage')||state.route.startsWith('#edit')?'manage':state.route.startsWith('#songs')?'songs':['#duties','#availability','#reminders'].includes(state.route)?'duties':'schedule';if(state.route==='#appearance')active=state.returnAppearance?.startsWith('#manage')?'manage':'schedule';return `<nav class="bottom-nav" aria-label="Main navigation">${items.map(([label,path,key])=>`<a href="${path}" data-route="${path}" class="${active===key?'active':''}" ${active===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span></a>`).join('')}</nav>`;}
function tabs(){let entries=[];if(state.route.startsWith('#manage')||state.route.startsWith('#edit')){entries=[['Schedule','#manage/schedule'],['Needs attention','#manage/attention'],['Members','#manage/members']];if(state.role==='admin')entries.push(['Settings','#manage/settings']);}else if(state.route.startsWith('#songs'))entries=[['My service','#songs/my-service'],['Songs','#songs/library'],['History','#songs/history']];else if(['#duties','#availability','#reminders'].includes(state.route))entries=[['Upcoming','#duties'],['Availability','#availability'],['Reminders','#reminders']];else if(state.route==='#schedule'||state.route.startsWith('#service'))entries=[['Schedule','#schedule']];return entries.length?`<nav class="tabs" aria-label="Workspace sections">${entries.map(([label,path])=>{const active=state.route===path||path==='#manage/schedule'&&state.route.startsWith('#edit')||path==='#manage/members'&&/^#manage\/(profile|invite|add-member)/.test(state.route)||path==='#songs/history'&&state.route==='#songs/history-detail';return `<a href="${path}" data-route="${path}" class="${active?'active':''}" ${active?'aria-current="page"':''}>${label}</a>`;}).join('')}</nav>`:'';}
function titleFor(){if(state.route.startsWith('#songs/song-detail'))return 'Song details';if(state.route.startsWith('#edit'))return 'Edit service';if(state.route.startsWith('#service'))return 'Service details';if(state.route.startsWith('#manage/profile'))return 'Member profile';return ({'#duties':'My next duty','#availability':'Your availability','#reminders':'Reminders','#schedule':'Schedule','#manage/schedule':'Schedule','#manage/attention':'Needs attention','#manage/members':'Members','#manage/invite':'Invite a member','#manage/add-member':'Add a member','#manage/exceptions':'Account exceptions','#manage/settings':'Settings','#songs/my-service':'My service','#songs/library':'Songs','#songs/history':'History','#songs/song-detail':'Song details','#songs/history-detail':'History entry','#appearance':'Appearance','#lock':'Worship Duty','#sign-in':'Sign in','#change-pin':'Change your member PIN','#unavailable':'Destination unavailable'})[state.route]||'Worship Duty';}
function header(){return `<header class="app-header"><div class="heading-copy"><div class="eyebrow">${canManage()?esc(state.department)+' / ':''}${roleNames[state.role]}</div><h1>${titleFor()}</h1></div><div class="header-actions">${button('Appearance','appearance','class="appearance-button"')}</div></header>`;}
function context(){return `<aside class="desktop-context"><p><strong>Worship Duty</strong><br>${appearances[state.appearance]}</p><p>${roleNames[state.role]} preview<br>Weekbook monthly schedule</p><p>Current snapshot where loaded.<br>Edits stay in this browser.</p>${link('All four designs','index.html','text-link')}</aside>`;}
// Four explicit composition renderers share information and actions.
const layouts={
 original:body=>`<div class="shell layout-original">${header()}<main id="main" class="workspace">${tabs()}${body}</main>${context()}</div>`,
 prism:body=>`<div class="shell layout-prism">${header()}${context()}<main id="main" class="workspace"><div class="prism-workspace">${tabs()}${body}</div></main></div>`,
 navy:body=>`<div class="shell layout-navy">${header()}<main id="main" class="workspace">${tabs()}<div class="paper-workspace">${body}</div></main>${context()}</div>`,
 aurora:body=>`<div class="shell layout-aurora">${header()}<main id="main" class="workspace">${tabs()}<div class="aurora-workspace">${body}</div></main></div>`
};
function render(){document.documentElement.dataset.appearance=state.appearance;document.title=`${titleFor()} | ${appearances[state.appearance]} | Weekbook`;const strip=`<div class="preview-strip"><span>Design preview · ${roleNames[state.role]} · ${appearances[state.appearance]}</span>${button('Preview controls','preview-controls')}</div>`;app.innerHTML=strip+layouts[state.appearance]((flash?`<div class="notice" role="status">${esc(flash)}</div>`:'')+(state.scene==='loading'?loading():screen()))+nav();}
function monthNav(){const i=months.indexOf(state.month);return `<nav class="month-nav" aria-label="Schedule month">${button('‹','month-prev',`aria-label="Previous month${i>0?': '+monthText(months[i-1]):''}" ${i<=0?'disabled':''}`)}<strong aria-live="polite">${monthText(state.month)}</strong>${button('›','month-next',`aria-label="Next month${i<months.length-1?': '+monthText(months[i+1]):''}" ${i>=months.length-1?'disabled':''}`)}</nav>`;}
function monthRecords(){return services.filter(s=>s.month===state.month).filter(s=>`${s.service} ${s.worship} ${s.date} ${dateText(s,{weekday:'long',month:'long',day:'numeric'})} ${timeText(s)} ${namesFor(s).join(' ')}`.toLowerCase().includes(state.search.toLowerCase())).filter(s=>!state.openOnly||openDuties(s).length);}
function serviceRow(record,editing=false){const names=namesFor(record);const open=openDuties(record).length;const summary=names.length?names.slice(0,2).join(' · ')+(names.length>2?` +${names.length-2}`:''):record.assignmentsLoaded?'Assignments not provided':'Assignments not loaded';const path=servicePath(editing?'edit':'service',record);const tile=`<span class="date-tile">${dateText(record,{weekday:'short'})}<b>${dateText(record,{day:'numeric'})}</b></span>`;const ribbon=state.appearance==='aurora'?`<span class="aurora-date-line">${dateText(record,{weekday:'short',month:'short',day:'numeric'})}</span>`:'';return `<a class="service-row ${state.selectedService===record.id?'selected':''}" href="${esc(path)}" data-route="${esc(path)}" data-record="${esc(record.id)}" aria-label="${editing?'Edit':'View'} ${esc(record.service)}, ${esc(record.worship)}, ${dateText(record,{month:'long',day:'numeric'})}, ${timeText(record)}. ${esc(summary)}">${state.appearance==='aurora'?'':tile}<span class="row-copy">${ribbon}<strong>${esc(record.service)} · ${timeText(record)}</strong><small>${esc(summary)}</small></span>${open?`<span class="row-badge warn">${open} open</span>`:''}<span class="row-arrow" aria-hidden="true">›</span></a>`;}
function weeks(records,editing){const groups=new Map();for(const r of records){const monday=new Date(r.dateObj);monday.setUTCDate(monday.getUTCDate()-(monday.getUTCDay()+6)%7);const key=monday.toISOString().slice(0,10);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}const rendered=[...groups].map(([date,records])=>{const label=new Date(`${date}T12:00:00Z`).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});const heading=`<h2 class="week-title">Week of ${label}</h2>`;const rows=`<div class="week-rows">${records.map(r=>serviceRow(r,editing)).join('')}</div>`;if(state.appearance==='prism')return `<section class="week prism-week" aria-label="Week of ${label}">${heading}${rows}</section>`;if(state.appearance==='original')return `<section class="week original-week">${heading}${rows}</section>`;if(state.appearance==='aurora')return `<section class="week aurora-week">${heading}${rows}</section>`;return `<section class="week paper-week">${heading}${rows}</section>`;});return `<div class="weeks">${rendered.join('')}</div>`;}
function departmentSelect(){return state.role==='admin'?`<label class="field" style="margin-bottom:12px">Department<select data-setting="department">${Object.keys(departments).map(name=>`<option ${state.department===name?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`:'';}
function schedule(manage=false){if(!services.length)return unavailable('Schedule not loaded','The current preview snapshot could not be loaded.',button('Reload preview','reload'));const records=monthRecords();const missing=services.filter(s=>s.month===state.month&&!s.assignmentsLoaded).length;return `${sourceLine()}${manage?departmentSelect():''}<div class="toolbar"><input type="search" id="schedule-search" data-search="schedule" aria-label="Search services or assigned members" placeholder="Search services or members" value="${esc(state.search)}">${manage?button('Open only','toggle-open',`aria-pressed="${state.openOnly}" ${state.openOnly?'class="primary"':''}`):''}</div>${monthNav()}<div class="list-summary"><span>${records.length} services${state.search||state.openOnly?' match':''}</span><span>${missing?'Assignments partly or not loaded':esc(state.department)}</span></div>${records.length?weeks(records,manage):`<div class="empty">${state.openOnly&&missing?'Unloaded assignments cannot be counted as open duties.':'No services match this month and search.'}${button('Clear filters','clear-search')}</div>`}<p class="footnote">Schedule snapshot. Omitted assignments are unknown. Local demonstration edits never update this snapshot.</p>`;}
function serviceHeading(s){return `<section class="service-heading"><div><h2>${esc(s.service)}</h2><p>${esc(s.worship)}<br>${dateText(s,{weekday:'long',month:'short',day:'numeric'})} · ${timeText(s)} PT</p></div><span class="date-tile">${dateText(s,{month:'short'})}<b>${dateText(s,{day:'numeric'})}</b></span></section>`;}
function stateBanner(){if(state.simulation==='normal'||state.simulation==='unsaved')return '';const labels={saving:['Saving, simulated','The demonstration is paused in its saving state.'],saved:['Saved, simulated','This is a visual success state, not a server acknowledgement.'],failed:['Save failed, simulated','Your demonstration draft is retained. Retry when ready.'],stale:['Newer changes detected, simulated','Your demonstration draft is retained. Review the conflict before retrying.']};const [title,copy]=labels[state.simulation]||[];return title?`<div class="state-banner" role="status"><strong>${title}</strong>${copy}${state.simulation==='stale'?button('Review changes','review-stale'):state.simulation==='failed'?button('Retry demonstration','retry-demo'):''}</div>`:'';}
function saveBar(key,label='Save changes'){const d=drafts.get(key);let status=d?.status==='saved'?'Saved in this browser':d?.dirty?'Unsaved demonstration edits':'No demonstration changes';if(d?.status==='failed')status='Local save failed. Draft retained.';if(busy)status='Saving to this browser...';return `${stateBanner()}<div class="save-bar"><div class="save-state" role="status" aria-live="polite"><strong>${status}</strong>Demonstration only</div>${button(busy?'Saving...':label,'save',`class="primary" data-key="${esc(key)}" ${busy||!d?.dirty&&state.simulation==='normal'?'disabled':''}`)}</div>`;}
function serviceDetail(edit=false){const s=getService(routeId());if(!s)return unavailable('Service unavailable','This service is not in the current design snapshot.',link('Back to schedule',canManage()?'#manage/schedule':'#schedule','button'));if(edit&&!canManage())return accessUnavailable();state.selectedService=s.id;const key=`service:${s.id}:${state.department}`;const initial=Object.fromEntries(currentDuties().map(d=>[d,assignmentValue(s,d).kind==='assigned'?assignmentValue(s,d).text:assignmentValue(s,d).kind==='open'?'':null]));const draft=draftFor(key,initial);const memberOptions=[...new Set([...members.map(m=>m.name),...Object.values(initial).filter(Boolean)])];const assignments=currentDuties().map(duty=>{const value=drawAssignment(s,duty);if(!edit)return `<div class="assignment"><span class="duty-label">${esc(duty)}</span><span class="assignment-value ${value.kind==='unknown'?'missing':''}">${esc(value.text)}</span></div>`;const v=draft.values[duty];return `<label class="assignment"><span class="duty-label">${esc(duty)}</span><select data-draft="${esc(key)}" data-field="${esc(duty)}" aria-label="${esc(duty)} assignment" ${!state.demoEditing?'disabled':''}><option value="__unknown" ${v===null?'selected':''}>${value.kind==='unknown'?'Not loaded':'Choose member'}</option><option value="" ${v===''?'selected':''}>Unassigned</option>${memberOptions.map(name=>`<option value="${esc(name)}" ${v===name?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;}).join('');return `${link('‹ Back to services',state.origin[state.route]||(edit?'#manage/schedule':'#schedule'),'back')}<div class="detail-layout">${serviceHeading(s)}<div class="detail-body"><div class="section-heading"><h2>${esc(state.department)}</h2><span class="small">${currentDuties().length} duties</span></div>${!s.assignmentsLoaded?'<div class="notice">Assignments not loaded in this design preview.</div>':''}${edit?`<p class="preview-note">${state.demoEditing?'Assignment changes below are local demonstrations. Eligibility and availability are not loaded.':'Assignment controls are shown read-only. Enable demonstration editing in Preview controls to try local changes.'}</p>`:''}<div class="assignments">${assignments}</div>${edit?`${button('Find a replacement','replacement','class="plain"')}${saveBar(key)}`:canManage()?link('Edit assignments',servicePath('edit',s),'button primary'):''}<p class="footnote">${edit?'No server save or notifications.':'Snapshot assignments are not an authenticated personal-duty view.'}</p></div></div>`;}
function myDuties(){const person=members.find(m=>m.id===state.selectedMember);const assigned=person?services.filter(s=>s.assignmentsLoaded&&Object.values(s.assignments).some(name=>name===person.name)&&(s.date>today||s.date===today&&s.minutes>=nowMinutes)):[];return `${sourceLine()}${person?`<p class="workspace-crumb">Previewing ${esc(person.name)}</p>`:''}${assigned.length?`<div class="section-heading"><h2>Next duty</h2></div>${serviceRow(assigned[0])}<div class="section-heading"><h2>Upcoming duties</h2></div>${weeks(assigned,false)}`:unavailable('Your duty assignments are not loaded','Choose a loaded member in Preview controls to inspect their snapshot assignments. Without a member and assignment data, no personal next duty can be identified.',button('Choose preview member','preview-controls')+link('View full schedule','#schedule','button'))}<div class="panel"><h2>Availability and reminders</h2><p>Manage these separately from your assigned duties.</p><div class="button-row">${link('Availability','#availability','button')}${link('Reminders','#reminders','button')}</div></div>`;}
function field(label,key,name,value,options,extra=''){return `<label class="field">${label}<select data-draft="${esc(key)}" data-field="${esc(name)}" ${extra}>${options.map(([v,l])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function availability(){const key='availability';const initial={scope:'all',department:'Worship',date:'',exception:'unavailable',...Object.fromEntries(serviceLabels.map(s=>[s,'unknown']))};const d=draftFor(key,initial);return `${unavailable('Current availability not loaded','The controls below demonstrate editing. All-department availability is the starting scope; department exceptions can be specified.')}<div class="panel"><h2>Applies to</h2><div class="field-grid" style="margin-top:12px">${field('Department scope',key,'scope',d.values.scope,[['all','All my departments'],['selected','Selected department']],'data-reflow="true"')}${d.values.scope==='selected'?field('Department',key,'department',d.values.department,Object.keys(departments).map(n=>[n,esc(n)])):''}</div></div><div class="section-heading"><h2>Recurring service times</h2></div><div class="field-grid two">${serviceLabels.map(label=>field(label,key,label,d.values[label],[['unknown','Not loaded'],['available','Available'],['unavailable','Unavailable']])).join('')}</div><div class="section-heading"><h2>Date exception</h2></div><div class="panel field-grid two"><label class="field">Exception date<input type="date" data-draft="availability" data-field="date" value="${esc(d.values.date)}"></label>${field('Availability',key,'exception',d.values.exception,[['unavailable','Unavailable'],['available','Available']])}</div><div class="notice">Becoming unavailable keeps existing assignments visible as Needs replacement until resolved.</div>${saveBar(key,'Save availability')}`;}
function reminders(){const key='reminders';const d=draftFor(key,{enabled:'unknown',timing:'unknown'});return `${unavailable('Reminder preferences not loaded','Notification permissions and the signed-in account are not connected. These controls demonstrate the preference layout.')}<div class="panel field-grid">${field('Duty reminders',key,'enabled',d.values.enabled,[['unknown','Not loaded'],['enabled','On'],['disabled','Off']])}${field('Reminder timing',key,'timing',d.values.timing,[['unknown','Not loaded'],['day','One day before'],['hour','One hour before']])}</div><div class="panel"><h2>Calendar</h2><p>Add duty dates to a calendar when an authenticated calendar feed is available.</p>${button('Add my duties to calendar','calendar')}</div>${saveBar(key,'Save reminders')}`;}
function attention(){const categories=[['requests','Requests'],['open','Open duties'],['conflicts','Conflicts'],['history','History']];const loadedMonth=services.filter(s=>s.month===state.month);const complete=loadedMonth.length>0&&loadedMonth.every(s=>s.assignmentsLoaded);const open=loadedMonth.filter(s=>openDuties(s).length);return `${departmentSelect()}<div class="category-tabs" aria-label="Attention categories">${categories.map(([key,label])=>button(label,'attention-category',`data-value="${key}" class="${state.attention===key?'active':''}" aria-pressed="${state.attention===key}"`)).join('')}</div>${state.attention==='open'?`${monthNav()}${!complete?'<div class="notice">Assignment coverage is incomplete. An absent assignment record is not an open duty.</div>':''}${open.length?weeks(open,true):unavailable(complete?'No explicitly unassigned duties in this snapshot':'Open duties not loaded',complete?'Only duties explicitly marked unassigned are counted.':'No complete open-duty count can be shown without assignment data.')}`:`<div class="toolbar"><input type="search" aria-label="Search ${state.attention}" placeholder="Search ${state.attention}" data-search="attention"></div>${unavailable(`${categories.find(c=>c[0]===state.attention)[1]} not loaded`,'Not loaded in this design preview. No request counts, conflict rows, or completed records have been invented.',button('View resolution controls','resolution'))}`}${state.role==='admin'?`<div class="panel"><h2>Account exceptions</h2><p>Missing or ambiguous accounts need administrator review.</p>${link('Open exceptions','#manage/exceptions','button')}</div>`:''}`;}
function pagination(page,pages,prefix){return `<div class="pagination" aria-label="${prefix} pages">${button('Previous',`${prefix}-prev`,page<=1?'disabled':'')}<span>Page ${page} of ${pages}</span>${button('Next',`${prefix}-next`,page>=pages?'disabled':'')}</div>`;}
function memberList(add=false){const results=members.filter(m=>m.name.toLowerCase().includes(state.memberSearch.toLowerCase()));const pages=Math.max(1,Math.ceil(results.length/10));state.memberPage=Math.min(state.memberPage,pages);return `${departmentSelect()}<div class="toolbar"><input type="search" id="member-search" data-search="members" aria-label="Search registered members by name" placeholder="Search registered members" value="${esc(state.memberSearch)}">${!add?link('Invite','#manage/invite','button'):''}</div>${members.length?`<p class="preview-note">Snapshot names only. Department membership and eligibility are not loaded.</p><div class="compact-list">${results.slice((state.memberPage-1)*10,state.memberPage*10).map(m=>link(`<span><strong>${esc(m.name)}</strong><small>${add?'Select for a local add-member draft':'Profile details not loaded'}</small></span><span aria-hidden="true">›</span>`,add?`#manage/add-member/${encodeURIComponent(m.id)}`:`#manage/profile/${encodeURIComponent(m.id)}`,'compact-row')).join('')}</div>${pagination(state.memberPage,pages,'members')}`:unavailable('Member names not loaded','Registered-member search is shown here. The design snapshot does not currently include names. No member rows are fabricated.')}${add?unavailable('Add to department','A registered account must be selected before adding a member. This preview does not create accounts or grant leadership.',button('View add-member controls','add-member-controls')):`<div class="button-row">${link('Add registered member','#manage/add-member','button')}${link('Profile layout','#manage/profile/preview','button')}</div>`}`;}
function profile(){const id=state.route.slice('#manage/profile/'.length);const member=members.find(m=>m.id===decodeURIComponent(id));const key=`profile:${id}`;const d=draftFor(key,{status:'unknown',schedulable:'unknown',...Object.fromEntries(currentDuties().map(name=>[name,false]))});return `${link('‹ Back to members','#manage/members','back')}<div class="panel"><h2>${member?esc(member.name):'Member profile'}</h2><p>${member?'Current profile details and department eligibility are not loaded.':'No member is selected. This is the profile layout only.'}</p></div><div class="field-grid two">${field('Membership status',key,'status',d.values.status,[['unknown','Not loaded'],['active','Active'],['inactive','Inactive']])}${field('Scheduling',key,'schedulable',d.values.schedulable,[['unknown','Not loaded'],['yes','Schedulable'],['no','Not schedulable']])}</div><div class="section-heading"><h2>Duty eligibility</h2><span class="small">Demonstration</span></div><p class="preview-note">Current eligibility is unknown. Checkboxes describe a local draft only.</p><div class="panel checkbox-grid">${currentDuties().map(duty=>`<label class="check-row"><input type="checkbox" data-draft="${esc(key)}" data-field="${esc(duty)}" ${d.values[duty]?'checked':''}><span>${esc(duty)}</span></label>`).join('')}</div><div class="button-row">${link('Shared availability','#availability','button')}${button('Profile history','profile-history')}</div>${saveBar(key,'Save profile')}`;}
function invite(){const key='invite';const d=draftFor(key,{department:state.department,prepared:false,revoked:false});return `${link('‹ Back to members','#manage/members','back')}<div class="panel"><h2>Invite to ${esc(state.department)}</h2><p>Accept while signed in. Links are single-use, revocable, and expire after seven days. They do not create an account or grant leadership.</p></div><div class="notice">Design preview only. No active invitation link will be generated.</div><div class="panel"><h2>${d.values.revoked?'Draft revoked':d.values.prepared?'Invitation draft ready':'Prepare an invitation draft'}</h2><p>${d.values.prepared?'This local draft demonstrates Share and Copy. It cannot be accepted as an invitation.':'The draft contains invitation wording only.'}</p><div class="button-row">${button(d.values.prepared?'Prepare again':'Prepare draft','prepare-invite','class="primary"')}${button('Revoke draft','revoke-invite',!d.values.prepared?'disabled':'')}</div>${d.values.prepared&&!d.values.revoked?`<div class="button-row">${button('Share draft','share-invite')}${button('Copy draft','copy-invite')}</div>`:''}</div>`;}
function settings(){if(state.role!=='admin')return accessUnavailable();const key='settings';const d=draftFor(key,{reminders:'unknown',calendar:'unknown'});return `<p class="preview-note">Administrator preview. Authorization is represented by the selected role, not enforced by a backend.</p><div class="panel field-grid">${field('Duty reminders',key,'reminders',d.values.reminders,[['unknown','Not loaded'],['on','Enabled'],['off','Disabled']])}${field('Calendar availability',key,'calendar',d.values.calendar,[['unknown','Not loaded'],['on','Enabled'],['off','Disabled']])}</div><div class="compact-list">${link('<span><strong>Account exceptions</strong><small>Missing or ambiguous accounts</small></span><span>›</span>','#manage/exceptions','compact-row')}${link('<span><strong>Appearance</strong><small>Original, Prism, Navy & Cream, Aurora</small></span><span>›</span>','#appearance','compact-row')}</div>${saveBar(key,'Save settings')}`;}
function exceptions(){if(state.role!=='admin')return accessUnavailable();return `${link('‹ Back to Needs attention','#manage/attention','back')}<div class="toolbar"><input type="search" aria-label="Search account exceptions" placeholder="Search account exceptions"></div>${unavailable('Account exceptions not loaded','No account cases are present in the snapshot. The exception detail and resolution controls can be inspected without inventing a person.',button('View exception controls','exception-controls'))}`;}
function serviceSelector(){const selected=selectedService();return `<label class="field" style="margin-bottom:14px">Service<select data-setting="song-service" aria-label="Select service for song planning">${services.map(s=>`<option value="${esc(s.id)}" ${s.id===selected?.id?'selected':''}>${dateText(s,{month:'short',day:'numeric'})} · ${esc(s.service)} · ${timeText(s)}</option>`).join('')||'<option>No service loaded</option>'}</select></label>`;}
function songDraft(){return draftFor(`songs:${selectedService()?.id||'none'}`,{selection:[],confirmed:false,confirmationState:'draft'});}
function songDuration(song){const sec=Number(song.durationSec);return Number.isFinite(sec)&&sec>0?`${Math.floor(sec/60)}:${String(Math.round(sec)%60).padStart(2,'0')}`:'Duration not loaded';}
function songMyService(){const person=members.find(m=>m.id===state.selectedMember);const assigned=person?services.find(s=>s.assignmentsLoaded&&s.assignments.Presider===person.name&&(s.date>today||s.date===today&&s.minutes>=nowMinutes)):null;if(!state.selectedService&&assigned)state.selectedService=assigned.id;const service=selectedService();const draft=songDraft();const picked=(draft.values.selection||[]).map(id=>songs.find(song=>song.id===id)).filter(Boolean);const simulation=state.songSimulation;const localStatus=draft.values.confirmed?'Confirmed in this browser':draft.values.confirmationState==='changed'?'Changed, confirm again':'Local draft';return `${!assigned?'<div class="notice">Your presider assignment is not loaded. The selected service below is for browsing, not claimed as your next assigned service.</div>':''}${serviceSelector()}${service?serviceHeading(service):''}${simulation!=='normal'?`<div class="state-banner"><strong>${({confirmed:'Confirmed',changed:'Changed, confirm again',draft:'Draft saved'})[simulation]} (preview simulation)</strong>No real service confirmation record is implied.</div>`:''}<div class="section-heading"><h2>${localStatus}</h2><span class="small">${picked.length} selected locally</span></div><p class="preview-note">Existing service setlists are not loaded. This list contains only your browser-local choices from the public catalog.</p>${picked.length?`<div class="compact-list">${picked.map((song,index)=>`<div class="compact-row"><span><strong>${esc(song.number)}. ${esc(song.title)}</strong><small>${esc(song.category)}</small></span><div class="inline-actions">${button('↑','move-song',`data-song="${esc(song.id)}" aria-label="Move ${esc(song.title)} earlier" ${index===0?'disabled':''}`)}${button('Remove','remove-song',`data-song="${esc(song.id)}" aria-label="Remove ${esc(song.title)} from local draft"`)}</div></div>`).join('')}</div>`:unavailable('Choose songs for a local draft',songs.length?'Browse the public catalog to add songs. Existing service songs and usage history remain unknown.':'The song catalog is not loaded. No song rows are invented.')}<div class="button-row">${link('Add songs','#songs/library','button')}${button('Confirm songs','song-confirm','class="primary"')}</div>${saveBar(draft.key,'Save draft')}<p class="footnote">Confirmation is browser-only. Editing confirmed selections requires confirmation again. No service or history record is updated.</p>`;}
function songsLibrary(){const categories=[...new Set(songs.map(song=>song.category).filter(Boolean))].sort();const results=songs.filter(song=>`${song.number} ${song.title} ${song.category}`.toLowerCase().includes(state.songSearch.toLowerCase())).filter(song=>state.songCategory==='all'||song.category===state.songCategory);const pages=Math.max(1,Math.ceil(results.length/10));state.songPage=Math.min(state.songPage,pages);return `${serviceSelector()}<div class="toolbar"><input type="search" id="song-search" data-search="songs" aria-label="Search song title or number" placeholder="Search song title or number" value="${esc(state.songSearch)}"><select data-setting="song-category" aria-label="Song category"><option value="all">All categories</option>${categories.map(category=>`<option value="${esc(category)}" ${state.songCategory===category?'selected':''}>${esc(category)}</option>`).join('')}</select></div><div class="category-tabs">${[['all','All songs'],['recent','Recently sung'],['planned','Planned']].map(([key,label])=>button(label,'song-filter',`data-value="${key}" class="${state.songFilter===key?'active':''}" aria-pressed="${state.songFilter===key}"`)).join('')}</div>${state.songFilter!=='all'?unavailable('Usage data not loaded','The public catalog is loaded, but recent sung and upcoming planned usage are not. No usage matches are fabricated.'):songs.length?`<div class="list-summary"><span>${results.length} matching songs</span><span>Public catalog</span></div><div class="compact-list">${results.slice((state.songPage-1)*10,state.songPage*10).map(song=>link(`<span><strong>${esc(song.number)}. ${esc(song.title)}</strong><small>${esc(song.category)}${song.durationSec?' · '+songDuration(song):''}</small></span><span aria-hidden="true">›</span>`,`#songs/song-detail/${encodeURIComponent(song.id)}`,'compact-row')).join('')||'<p class="empty">No catalog songs match this search.</p>'}</div>${pagination(state.songPage,pages,'songs')}`:unavailable('Song catalog not loaded','No song titles or numbers have been invented.')}${link('Return to my service','#songs/my-service','button primary')}`;}
function songDetail(){let id=state.selectedSong;if(state.route.startsWith('#songs/song-detail/')){try{id=decodeURIComponent(state.route.slice('#songs/song-detail/'.length));state.selectedSong=id;}catch(_){}}const song=songs.find(song=>song.id===id);if(!song)return `${link('‹ Back to songs','#songs/library','back')}${unavailable('Song not selected','Choose a loaded catalog song to inspect details.',link('Browse catalog','#songs/library','button'))}`;const draft=songDraft();const included=(draft.values.selection||[]).includes(song.id);return `${link('‹ Back to songs','#songs/library','back')}<section class="panel"><p class="eyebrow">Song ${esc(song.number)}</p><h2>${esc(song.title)}</h2><p>${esc(song.category)}</p><dl class="key-values"><dt>Duration</dt><dd>${songDuration(song)}</dd><dt>Last sung</dt><dd>Not loaded</dd><dt>Upcoming planned use</dt><dd>Not loaded</dd><dt>Repeat warning</dt><dd>Requires usage data</dd></dl></section><div class="button-row">${button(included?'Added to local draft':'Add to draft','add-song',`class="primary" ${included?'disabled':''}`)}${button('Play song','play-song')}</div>${link('Return to my service','#songs/my-service','button')}<p class="footnote">Public catalog details are loaded. Usage and playable media are not supplied. Repeat warnings remain advisory.</p>`;}
function songHistory(){return `<div class="toolbar"><input type="search" id="history-search" data-search="history" aria-label="Search song and service history" placeholder="Search song or service" value="${esc(state.historySearch)}"><select data-setting="history-filter" aria-label="History source"><option value="all">All history</option><option value="automatic" ${state.historyFilter==='automatic'?'selected':''}>Automatic</option><option value="corrected" ${state.historyFilter==='corrected'?'selected':''}>Corrected</option></select></div>${unavailable('Song history not loaded','Search, source filters, and correction controls are shown. There are no history rows or statistics to calculate from this snapshot.',link('Inspect history entry','#songs/history-detail','button'))}<div class="panel"><h2>Recording confirmed songs</h2><p>Confirmed lists are recorded after the service window. Unconfirmed lists are not automatically added. Authorized corrections retain their history.</p></div>`;}
function historyDetail(){return `${link('‹ Back to history','#songs/history','back')}<div class="panel"><h2>History entry</h2><dl class="key-values"><dt>Service</dt><dd>Not loaded</dd><dt>Song list</dt><dd>Not loaded</dd><dt>Recording source</dt><dd>Automatic or corrected</dd><dt>Usage statistics</dt><dd>Not loaded</dd></dl></div>${unavailable('Correction requires a loaded entry','The correction dialog demonstrates the authorized action and confirmation step.',button('Correct history','correct-history'))}`;}
function appearanceScreen(){return `<p class="preview-note">All four use Weekbook's shared current month, selections, drafts, and actions.</p><div class="appearance-grid">${Object.entries(appearances).map(([key,name])=>`<button class="appearance-choice ${key===state.appearance?'active':''}" data-action="choose-appearance" data-value="${key}" aria-pressed="${key===state.appearance}"><span class="mini-layout ${key}" aria-hidden="true"><i></i><i></i><i></i><i></i></span><strong>${esc(name)}</strong><small>${({original:'Straight rows and full-width fields.',prism:'Date spine and stepped weekly groups.',navy:'Paper groups and paired assignments.',aurora:'Date ribbons and soft horizontal cards.'})[key]}</small></button>`).join('')}</div><p class="footnote">Appearance applies immediately and is remembered in this browser.</p>${button('Return to workspace','return-appearance','class="plain"')}`;}
function accessUnavailable(){return unavailable('This workspace needs another role','Choose a leader or administrator role in Preview controls to inspect management, or Presider to inspect song planning.',button('Preview controls','preview-controls'));}
function accessScreen(signIn=false){return `<section class="panel access-card"><h2>${signIn?'Sign in':'Enter site passcode'}</h2><p>${signIn?'Select your member account and enter its 4 to 6 digit PIN.':'Enter the site passcode to continue.'}</p>${signIn?`<label class="field" style="margin-top:14px">Member account<select disabled aria-label="Member account selection not connected"><option>Select your member account</option>${members.map(member=>`<option>${esc(member.name)}</option>`).join('')}</select></label><input type="password" inputmode="numeric" pattern="[0-9]*" minlength="4" maxlength="6" placeholder="Member PIN" aria-label="Member PIN entry not connected" disabled>`:'<input type="password" placeholder="Site passcode" aria-label="Site passcode entry not connected" disabled>'}${button(signIn?'Continue to role preview':'Continue to sign-in preview',signIn?'access-continue':'access-sign-in','class="primary"')}${signIn?button('Preview required PIN change','access-change-pin','class="plain"'):''}<p class="footnote">Design preview. Fields are disabled. No credentials are collected. ${appearances[state.appearance]} applies before this screen.</p></section>`;}
function changePin(){return `<section class="panel access-card"><h2>Change your member PIN</h2><p>Choose a new 4 to 6 digit member PIN before continuing.</p><input type="password" inputmode="numeric" pattern="[0-9]*" minlength="4" maxlength="6" placeholder="New PIN" aria-label="New member PIN entry not connected" disabled><input type="password" inputmode="numeric" pattern="[0-9]*" minlength="4" maxlength="6" placeholder="Repeat new PIN" aria-label="Repeat new member PIN entry not connected" disabled>${button('Continue to role preview','access-continue','class="primary"')}<p class="footnote">Required PIN-change layout only. No credentials are entered or changed.</p></section>`;}
function loading(){return `<section aria-label="Loading preview" aria-busy="true"><p class="preview-note">Loading state simulation</p><h2>Loading your workspace</h2><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>${button('Retry loading','retry-loading')}${button('Use Original for recovery','original-recovery','class="plain"')}</section>`;}
function screen(){const r=state.route;if(r.startsWith('#manage')&&!canManage()||r.startsWith('#edit')&&!canManage()||r.startsWith('#songs')&&!canSongs())return accessUnavailable();if(r.startsWith('#songs/song-detail/'))return songDetail();if(r.startsWith('#edit/'))return serviceDetail(true);if(r.startsWith('#service/'))return serviceDetail();if(r.startsWith('#manage/profile/'))return profile();if(r.startsWith('#manage/add-member/'))return addMemberSelection();switch(r){case '#duties':return myDuties();case '#availability':return availability();case '#reminders':return reminders();case '#schedule':return schedule();case '#manage/schedule':return schedule(true);case '#manage/attention':return attention();case '#manage/members':return memberList();case '#manage/add-member':return memberList(true);case '#manage/invite':return invite();case '#manage/settings':return settings();case '#manage/exceptions':return exceptions();case '#songs/my-service':return songMyService();case '#songs/library':return songsLibrary();case '#songs/song-detail':return songDetail();case '#songs/history':return songHistory();case '#songs/history-detail':return historyDetail();case '#appearance':return appearanceScreen();case '#lock':return accessScreen();case '#sign-in':return accessScreen(true);case '#change-pin':return changePin();default:return unavailable('Destination unavailable','This destination is unavailable or outside the selected preview role.',link('Open your workspace',defaults[state.role],'button primary'));}}
function addMemberSelection(){const id=decodeURIComponent(state.route.slice('#manage/add-member/'.length));const member=members.find(m=>m.id===id);return `${link('‹ Back to member search','#manage/add-member','back')}<div class="panel"><h2>${member?esc(member.name):'Member not loaded'}</h2><p>Registered-account and department checks are not connected.</p>${button('Add to department, demonstration','add-member-controls',!member?'disabled':'')}</div>`;}
function info(title,body,actions=''){infoDialog.innerHTML=`<div class="drawer-head"><h2 id="info-title">${title}</h2>${button('Close','close-info','class="close-button"')}</div>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!infoDialog.open)infoDialog.showModal();}
function previewControls(){previewDialog.innerHTML=`<div class="drawer-head"><h2 id="preview-title">Design preview controls</h2>${button('Close','close-preview','class="close-button"')}</div><p>These controls are outside the app design. Role switching is not authentication. State examples are explicitly simulated.</p><div class="drawer-section"><label class="field">Role preview<select id="preview-role">${Object.entries(roleNames).map(([key,name])=>`<option value="${key}" ${key===state.role?'selected':''}>${name}</option>`).join('')}</select></label><label class="field">Member to preview<select id="preview-member" ${!members.length?'disabled':''}><option value="">${members.length?'No member selected':'Member names not loaded'}</option>${members.map(m=>`<option value="${esc(m.id)}" ${m.id===state.selectedMember?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label class="check-row"><input type="checkbox" id="preview-editing" ${state.demoEditing?'checked':''}><span>Enable browser-only demonstration assignment editing</span></label></div><div class="drawer-section"><label class="field">Save-state simulation<select id="preview-state">${[['normal','Normal'],['unsaved','Unsaved'],['saving','Saving'],['saved','Saved'],['failed','Failed'],['stale','Stale edit']].map(([key,name])=>`<option value="${key}" ${key===state.simulation?'selected':''}>${name}</option>`).join('')}</select></label><label class="field">Song confirmation simulation<select id="preview-song-state">${[['normal','No simulated status'],['draft','Draft saved'],['confirmed','Confirmed'],['changed','Changed, confirmation required']].map(([key,name])=>`<option value="${key}" ${key===state.songSimulation?'selected':''}>${name}</option>`).join('')}</select></label></div><div class="drawer-section"><label class="field">Startup or destination preview<select id="preview-scene">${[['normal','Current workspace'],['lock','Site lock'],['sign-in','Sign in'],['change-pin','Required member PIN change'],['loading','Loading and recovery'],['unavailable','Unavailable notification destination']].map(([key,name])=>`<option value="${key}" ${key===state.scene?'selected':''}>${name}</option>`).join('')}</select></label></div><div class="dialog-actions">${button('Apply preview','apply-preview','class="primary"')}</div><p>Personal names, actual requests, song titles, history, and permissions are displayed only if loaded. No missing records are fabricated.</p>`;previewDialog.showModal();}
function leaveGuard(action,next){if(busy){info('Save in progress','<p>The local demonstration save is finishing. Try navigation again afterward.</p>');return;}const d=activeDraft();const withinSongs=state.route.startsWith('#songs/')&&next?.startsWith('#songs/');if(d?.dirty&&!withinSongs){pendingLeave=action;leaveDialog.showModal();return;}action();}
function navigate(next,replace=false){if(next===state.route)return;if(next==='index.html'){leaveGuard(()=>{location.href='index.html';},next);return;}leaveGuard(()=>{state.scroll[state.route]=window.scrollY;const previous=state.route;if(next.startsWith('#edit/')||next.startsWith('#service/')){state.origin[next]=previous;try{state.selectedService=decodeURIComponent(next.split('/').slice(1).join('/'));}catch(_){}}if(next==='#appearance')state.returnAppearance=previous;state.route=next;state.scene='normal';flash='';history[replace?'replaceState':'pushState']({route:next},'',next);render();window.scrollTo(0,state.scroll[next]||0);},next);}
function updateStatus(){const y=window.scrollY;const focused=document.activeElement;const id=focused?.id;let selection;try{selection=focused?.selectionStart;}catch(_){}render();window.scrollTo(0,y);if(id){const el=document.getElementById(id);el?.focus({preventScroll:true});try{if(selection!==undefined)el?.setSelectionRange(selection,selection);}catch(_){}}}
async function save(key){const d=drafts.get(key);if(!d||busy)return;if(state.simulation==='saving'){info('Saving state simulation','<p>This state is paused for design inspection. Set the save-state simulation to Normal to make a browser-only save.</p>');return;}if(state.simulation==='failed'||state.simulation==='stale'){d.status=state.simulation;render();return;}busy=true;render();await new Promise(resolve=>setTimeout(resolve,220));try{stored[key]=clone(d.values);localStorage.setItem(storageKey,JSON.stringify(stored));d.baseline=clone(d.values);d.dirty=false;d.status='saved';}catch(_){d.status='failed';d.dirty=true;}busy=false;render();}
function invitationText(){return `Worship Duty invitation draft\nDepartment: ${state.department}\nSign in to accept a single-use invitation. An active link would expire after seven days.\nDESIGN PREVIEW ONLY: No active invitation link exists.`;}
async function copyDraft(){try{await navigator.clipboard.writeText(invitationText());info('Draft copied','<p>Invitation wording was copied. No active link or invitation was created.</p>');}catch(_){info('Copy invitation draft',`<p>Select and copy this demonstration wording.</p><textarea rows="6" readonly aria-label="Invitation draft text">${esc(invitationText())}</textarea>`);}}
function replacementDialog(){info('Find a replacement',`<p>Eligibility, availability, and existing duties are not loaded. No candidate can be presented as an eligible replacement.</p><label class="field">Search members<input type="search" id="replacement-search" placeholder="Search registered members" aria-label="Search replacement members"></label><div id="replacement-results"><p>${members.length?'Enter a name to inspect snapshot matches.':'Member names not loaded in this design preview.'}</p></div><div class="notice">Prioritize available members without another duty. A second duty requires an advisory warning. No replacement keeps the duty open.</div>`,button('Keep duty unchanged','close-info'));}
function resolutionDialog(){info('Resolve a request',`<p>No request is loaded. This is the resolution layout, without an invented person or request.</p><dl class="key-values"><dt>Request</dt><dd>Not loaded</dd><dt>Current assignment</dt><dd>Not loaded</dd><dt>Replacement eligibility</dt><dd>Not loaded</dd></dl><p>Save the assignment change and resolve the request together. A failed or stale save must leave it unresolved.</p>`,button('Find replacement','replacement')+button('Save and resolve','resolution-unavailable','class="primary"'));}
function unavailableAction(title,detail){info(title,`<p>${detail}</p><p>No live operation was attempted.</p>`);}
const actions={
 'preview-controls':previewControls,'close-preview':()=>previewDialog.close(),'close-info':()=>infoDialog.close(),
 'appearance':()=>{state.returnAppearance=state.route;state.scroll[state.route]=window.scrollY;state.route='#appearance';history.pushState({route:state.route},'',state.route);render();window.scrollTo(0,0);},
 'return-appearance':()=>{const next=state.returnAppearance||defaults[state.role];state.route=next;history.replaceState({route:next},'',next);render();window.scrollTo(0,state.scroll[next]||0);},
 'choose-appearance':el=>{state.appearance=el.dataset.value;try{localStorage.setItem('weekbook-appearance-v4',state.appearance);}catch(_){}const url=new URL(location.href);url.searchParams.set('appearance',state.appearance);history.replaceState({route:state.route},'',url);render();},
 'month-prev':()=>changeMonth(-1),'month-next':()=>changeMonth(1),'toggle-open':()=>{state.openOnly=!state.openOnly;render();},'clear-search':()=>{state.search='';state.openOnly=false;render();},
 'reload':()=>location.reload(),'save':el=>save(el.dataset.key),'replacement':replacementDialog,'resolution':resolutionDialog,
 'resolution-unavailable':()=>unavailableAction('Resolution unavailable','A request, current assignment version, and eligible replacement must be loaded before Save and resolve can run.'),
 'calendar':()=>unavailableAction('Calendar unavailable','The personal duty calendar is not loaded. No subscription or export has been created.'),
 'attention-category':el=>{state.attention=el.dataset.value;render();},'members-prev':()=>{state.memberPage--;render();window.scrollTo(0,0);},'members-next':()=>{state.memberPage++;render();window.scrollTo(0,0);},
 'profile-history':()=>unavailableAction('Profile history not loaded','The history and provenance layout will show who changed membership, eligibility, and availability when those records are loaded.'),
 'add-member-controls':()=>info('Add registered member',`<p>Selected department: ${esc(state.department)}</p><p>Registered identity and existing membership must be checked before adding. No account is created and no leadership is granted.</p>`,button('Keep as local draft','add-member-draft','class="primary"')),
 'add-member-draft':()=>{infoDialog.close();flash='Add-member demonstration prepared. No membership was changed.';render();},
 'prepare-invite':()=>{const d=draftFor('invite',{department:state.department});d.values={department:state.department,prepared:true,revoked:false};d.dirty=false;d.status='unchanged';render();},
 'revoke-invite':()=>{const d=drafts.get('invite');if(d){d.values.revoked=true;d.values.prepared=false;}render();},'copy-invite':copyDraft,
 'share-invite':()=>info('Share invitation draft',`<p>This is an in-preview share sheet. Nothing is sent to another app or person.</p><textarea rows="6" readonly aria-label="Invitation wording">${esc(invitationText())}</textarea>`,button('Copy draft','copy-invite','class="primary"')),
 'exception-controls':()=>info('Account exception',`<p>No exception record is loaded. The intended controls let an administrator search registered accounts, choose a matching account, and resolve ambiguity.</p><label class="field">Registered-member search<input type="search" placeholder="Search by name" aria-label="Exception member search"></label><p>Matching accounts: not loaded.</p>`,button('Resolve exception','exception-unavailable','class="primary"')),
 'exception-unavailable':()=>unavailableAction('Exception resolution unavailable','A real exception and a verified matching account must be loaded before resolving.'),
 'song-filter':el=>{state.songFilter=el.dataset.value;render();},
 'songs-prev':()=>{state.songPage--;render();window.scrollTo(0,0);},'songs-next':()=>{state.songPage++;render();window.scrollTo(0,0);},
 'song-save':()=>save(songDraft().key),
 'song-confirm':()=>{const d=songDraft();if(!(d.values.selection||[]).length){info('Choose songs first','<p>Add catalog songs to a local draft before confirming. Existing live setlists are not loaded.</p>',button('Browse catalog','browse-catalog','class="primary"'));return;}info('Confirm local song draft','<p>Confirm these browser-local selections? This does not confirm songs for the live service or create song history.</p>',button('Confirm in this browser','confirm-local-songs','class="primary"'));},
 'browse-catalog':()=>{infoDialog.close();navigate('#songs/library');},
 'confirm-local-songs':()=>{const d=songDraft();d.values.confirmed=true;d.values.confirmationState='confirmed';d.dirty=true;infoDialog.close();save(d.key);},
 'add-song':()=>{const song=songs.find(s=>s.id===state.selectedSong);if(!song)return;const d=songDraft();if(!(d.values.selection||[]).includes(song.id)){d.values.selection=[...(d.values.selection||[]),song.id];markSongDraftChanged(d);}flash='Song added to your browser-local draft.';render();},
 'remove-song':el=>{const d=songDraft();d.values.selection=(d.values.selection||[]).filter(id=>id!==el.dataset.song);markSongDraftChanged(d);render();},
 'move-song':el=>{const d=songDraft();const list=d.values.selection||[];const index=list.indexOf(el.dataset.song);if(index>0){[list[index-1],list[index]]=[list[index],list[index-1]];markSongDraftChanged(d);render();}},
 'play-song':()=>unavailableAction('Song media not loaded','A playable source must be loaded before this control can play audio.'),
 'correct-history':()=>info('Correct history','<p>No history entry is loaded. An authorized correction would retain the original source, record the correction, and update song usage consistently.</p><label class="field">Correction note<textarea rows="2" placeholder="Demonstration note only" aria-label="History correction demonstration note"></textarea></label>',button('Preview correction','history-correction','class="primary"')),
 'history-correction':()=>info('Correction preview','<p>The correction layout has been demonstrated. No history or usage record was changed.</p>'),
 'review-stale':()=>info('Review changes, simulated','<p>The comparison layout preserves your draft beside the newer saved values. No newer record is loaded here, so values are not invented.</p><dl class="key-values"><dt>Your draft</dt><dd>Retained locally</dd><dt>Newer saved version</dt><dd>Not loaded</dd></dl>',button('Return to draft','close-info')+button('Retry demonstration','retry-demo','class="primary"')),
 'retry-demo':()=>{state.simulation='normal';if(infoDialog.open)infoDialog.close();const d=activeDraft();if(d){d.dirty=true;save(d.key);}else{flash='Demonstration reset. Your local selection is preserved.';render();}},
 'access-sign-in':()=>navigate('#sign-in'),'access-change-pin':()=>navigate('#change-pin'),'access-continue':()=>navigate(defaults[state.role]),
 'retry-loading':()=>{state.scene='normal';render();},'original-recovery':()=>{state.appearance='original';state.scene='normal';flash='Original recovery preview. Your saved appearance preference was not overwritten.';render();},
 'stay':()=>{pendingLeave=null;leaveDialog.close();},'discard-leave':()=>{const d=activeDraft();if(d){d.values=clone(d.baseline);d.dirty=false;d.status='unchanged';}leaveDialog.close();const action=pendingLeave;pendingLeave=null;action?.();},
 'apply-preview':()=>{const role=document.querySelector('#preview-role').value;const member=document.querySelector('#preview-member').value;const editing=document.querySelector('#preview-editing').checked;const simulation=document.querySelector('#preview-state').value;const songSimulation=document.querySelector('#preview-song-state').value;const scene=document.querySelector('#preview-scene').value;previewDialog.close();leaveGuard(()=>{const changedRole=role!==state.role;state.role=role;state.selectedMember=member;state.demoEditing=editing;state.simulation=simulation;state.songSimulation=songSimulation;state.scene=scene;flash='';if(changedRole)state.route=defaults[role];if(scene==='lock'||scene==='sign-in'||scene==='change-pin'||scene==='unavailable')state.route='#'+scene;if(simulation!=='normal'&&!activeDraft()&&canManage()&&services.length&&scene==='normal'){state.route=servicePath('edit',selectedService());}const url=new URL(location.href);url.searchParams.set('role',role);url.hash=state.route;history.replaceState({route:state.route},'',url);render();if(simulation==='unsaved'){const d=activeDraft();if(d){d.dirty=true;d.status='unsaved';render();}}window.scrollTo(0,0);},role!==state.role?defaults[role]:state.route);}
};
function markSongDraftChanged(d){if(d.values.confirmed||d.values.confirmationState==='confirmed')d.values.confirmationState='changed';d.values.confirmed=false;d.dirty=true;d.status='unsaved';}
function changeMonth(delta){const index=months.indexOf(state.month)+delta;if(index<0||index>=months.length)return;state.month=months[index];state.scroll[state.route]=0;render();window.scrollTo(0,0);}
document.addEventListener('click',event=>{const routeLink=event.target.closest('[data-route]');if(routeLink){if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();navigate(routeLink.dataset.route);return;}const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();actions[el.dataset.action]?.(el);});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.draft){const d=drafts.get(el.dataset.draft);if(!d)return;d.values[el.dataset.field]=el.type==='checkbox'?el.checked:el.value==='__unknown'?null:el.value;d.dirty=true;d.status='unsaved';const save=app.querySelector('[data-action="save"]');if(save)save.disabled=false;const status=app.querySelector('.save-state strong');if(status)status.textContent='Unsaved demonstration edits';if(el.dataset.reflow)updateStatus();return;}if(el.dataset.search==='schedule'){state.search=el.value;updateStatus();}else if(el.dataset.search==='members'){state.memberSearch=el.value;state.memberPage=1;updateStatus();}else if(el.dataset.search==='songs'){state.songSearch=el.value;state.songPage=1;updateStatus();}else if(el.dataset.search==='history'){state.historySearch=el.value;}else if(el.id==='replacement-search'){const matches=members.filter(m=>m.name.toLowerCase().includes(el.value.toLowerCase())).slice(0,6);document.querySelector('#replacement-results').innerHTML=matches.length?`<div class="compact-list">${matches.map(m=>`<div class="compact-row"><span><strong>${esc(m.name)}</strong><small>Eligibility and availability not loaded</small></span></div>`).join('')}</div>`:'<p>No loaded member matches. This does not establish whether a replacement exists.</p>';}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.setting==='department'){leaveGuard(()=>{state.department=el.value;render();},state.route);}else if(el.dataset.setting==='song-service'){state.selectedService=el.value;render();}else if(el.dataset.setting==='song-category'){state.songCategory=el.value;state.songPage=1;render();}else if(el.dataset.setting==='history-filter'){state.historyFilter=el.value;}});
leaveDialog.addEventListener('cancel',()=>{pendingLeave=null;});
window.addEventListener('beforeunload',event=>{if(busy||[...drafts.values()].some(d=>d.dirty)){event.preventDefault();event.returnValue='';}});
window.addEventListener('popstate',()=>{const next=location.hash||defaults[state.role];const d=activeDraft();if(d?.dirty&&!(state.route.startsWith('#songs/')&&next.startsWith('#songs/'))){history.replaceState({route:state.route},'',state.route);leaveGuard(()=>{state.route=next;history.replaceState({route:next},'',next);render();window.scrollTo(0,state.scroll[next]||0);},next);}else{state.scroll[state.route]=window.scrollY;state.route=next;state.scene='normal';render();window.scrollTo(0,state.scroll[next]||0);}});
if(state.route==='#schedule'&&state.role==='leader'&&!query.has('role'))state.route='#manage/schedule';
history.replaceState({route:state.route},'',state.route);
render();
